q = int(input())
from math import log, floor

def ancestor(x):
	ans = {1}
	while x != 1:
		ans.add(x)
		if x % 2:
			x = (x - 1) // 2
		else:
			x //= 2
	return ans

def path(x, y):
	x = ancestor(x)
	y = ancestor(y)
	common = x & y
	return {max(common)} | y - common | x - common
